func (n *sros) cpmSlot() (string, error) {
	// Prefer slot A, fall back to slot B. Slots are accepted in either case.
	for _, comp := range n.kindSpecificCfg().Components {
		if strings.EqualFold(comp.Slot, slotAName) {
